import (
	context "context"
	fern "github.com/go-oauth-token-nullable/fern"
	fernclient "github.com/go-oauth-token-nullable/fern/client"
	option "github.com/go-oauth-token-nullable/fern/option"
)

client := fernclient.NewClient(
	option.WithClientCredentials(
		"<YOUR_CLIENT_ID>",
		"<YOUR_CLIENT_SECRET>",
	),
)
response, err := client.Auth.GetTokenWithClientCredentials(
	context.TODO(),
	&fern.GetTokenRequest{
		ClientID:     "my_oauth_app_123",
		ClientSecret: "sk_live_abcdef123456789",
	},
)
